import{_ as o,r as i,o as n,c as l,a as e,b as r,d as c,e as s}from"./app-6be1f847.js";const d="/vuepress_blog/assets/AccountAuthenticationProvider-ec660838.png",a="/vuepress_blog/assets/Authentication-ebec3a18.png",u="/vuepress_blog/assets/UserDetails-a4a772ad.png",p="/vuepress_blog/assets/custom_token-311829ab.png",g={},h=s('<p>Spring Security’s Servlet support is based on Servlet Filters.Spring provides a Filter implementation named <code>DelegatingFilterProxy</code> that allows bridging between the Servlet container’s lifecycle and Spring’s ApplicationContext.</p><h2 id="认证流程" tabindex="-1"><a class="header-anchor" href="#认证流程" aria-hidden="true">#</a> 认证流程</h2><p>Spring Security 的认证流程涉及多个组件和步骤，它基于过滤器链（<code>SecurityFilterChain</code>）来实现。以下是 Spring Security 认证过程的概览：</p><ol><li><p><strong>请求拦截</strong>：</p><ul><li>当用户尝试访问受保护的资源时，Spring Security 的过滤器链会首先拦截这个请求。</li></ul></li><li><p><strong>生成未认证的 Authentication 对象</strong>：</p><ul><li>如果请求需要认证，一个未认证的 <code>Authentication</code> 对象会被创建，并且通常包含用户名和密码等信息。</li></ul></li><li><p><strong>调用 AuthenticationManager 进行认证</strong>：</p><ul><li>该 <code>Authentication</code> 对象被传递给 <code>AuthenticationManager</code> 来进行认证。</li><li><code>ProviderManager</code> 是 <code>AuthenticationManager</code> 的默认实现，它内部维护了一个 <code>AuthenticationProvider</code> 列表，每个 <code>AuthenticationProvider</code> 都可以处理特定类型的认证逻辑。</li></ul></li><li><p><strong>认证处理</strong>：</p><ul><li><code>AuthenticationProvider</code> 实现了具体的认证逻辑。例如，<code>DaoAuthenticationProvider</code> 用于验证数据库中的用户信息。</li><li>如果认证成功，<code>AuthenticationProvider</code> 返回一个完全填充的 <code>Authentication</code> 对象，其中包含用户的权限信息；如果认证失败，则抛出异常。</li></ul></li><li><p><strong>认证结果处理</strong>：</p><ul><li>如果认证成功，<code>Authentication</code> 对象将被存储在 <code>SecurityContextHolder</code> 中，使得当前线程能够访问到当前已认证的用户信息。</li><li>如果认证失败，可能会重定向到登录页面或返回错误消息提示用户重新登录。</li></ul></li><li><p><strong>安全上下文管理</strong>：</p><ul><li><code>SecurityContextHolder</code> 使用 <code>ThreadLocal</code> 存储 <code>SecurityContext</code>，确保每个请求都能获取到当前用户的认证信息。</li><li><code>SecurityContext</code> 包含了 <code>Authentication</code> 对象。</li></ul></li><li><p><strong>权限验证</strong>：</p><ul><li>在 <code>FilterSecurityInterceptor</code> 中，从 <code>SecurityContextHolder</code> 获取 <code>Authentication</code> 对象，并检查用户是否拥有访问所需资源的权限。</li></ul></li><li><p><strong>资源访问</strong>：</p><ul><li>如果用户通过了认证并具有适当的权限，则允许访问所请求的资源；否则，访问将被拒绝，并可能引发 <code>AccessDeniedException</code> 或者要求用户再次登录。</li></ul></li></ol><p>此外，Spring Security 支持多种认证方式，如表单登录、HTTP Basic、OAuth2 和 JWT 等。你可以根据需求选择合适的认证方式，并通过自定义过滤器和处理器来扩展认证流程。例如，在使用 JWT 时，你可能需要编写一个自定义的过滤器来解析 JWT 并设置 <code>SecurityContextHolder</code>。这通常涉及到实现 <code>OncePerRequestFilter</code> 类并覆盖 <code>doFilterInternal</code> 方法。</p><h2 id="第三方登录流程概述" tabindex="-1"><a class="header-anchor" href="#第三方登录流程概述" aria-hidden="true">#</a> 第三方登录流程概述</h2><p>第三方登录通常基于OAuth 2.0或OpenID Connect（OIDC）协议来实现。以下是使用Spring Security集成第三方登录（以Google为例）的典型流程：</p><ol><li><p><strong>用户发起请求</strong>：</p><ul><li>用户点击应用界面上的“使用XXX登录”按钮，比如“使用Google登录”。</li></ul></li><li><p><strong>重定向到身份提供商</strong>：</p><ul><li>应用将用户重定向到Google的身份验证页面，同时传递一些必要的参数，如客户端ID、回调URL（redirect URI）、作用域（scope）等。</li></ul></li><li><p><strong>用户授权</strong>：</p><ul><li>在Google的身份验证页面上，用户输入其凭据并同意授予应用访问其某些信息的权限。</li></ul></li><li><p><strong>获取授权码</strong>：</p><ul><li>如果用户成功授权，Google会重定向用户回到应用提供的回调URL，并在URL中附带一个授权码（authorization code）。</li></ul></li><li><p><strong>交换授权码为访问令牌</strong>：</p><ul><li>应用接收到这个授权码后，会向Google发送一个HTTP请求，包含授权码、客户端ID、客户端密钥以及回调URL，来换取访问令牌（access token）。</li></ul></li><li><p><strong>获取用户信息</strong>：</p><ul><li>应用使用得到的访问令牌向Google的用户信息端点发起请求，获取用户的个人信息，如用户名、电子邮件地址等。</li></ul></li><li><p><strong>创建或更新本地用户账户</strong>：</p><ul><li>根据从Google获得的用户信息，在本地数据库中查找是否存在对应的用户记录。如果不存在，则可能需要提示用户绑定现有账户或自动创建新账户。</li></ul></li><li><p><strong>建立用户会话</strong>：</p><ul><li>成功获取用户信息之后，应用会在本地建立一个用户会话，使用户保持登录状态，然后重定向用户到应用内的目标页面。</li></ul></li><li><p>Spring Security 集成步骤</p><ul><li><strong>添加依赖</strong>：在<code>pom.xml</code>或<code>build.gradle</code>文件中添加<code>spring-boot-starter-oauth2-client</code>依赖。</li><li><strong>配置第三方登录提供商</strong>：在<code>application.yml</code>或<code>application.properties</code>文件中设置OAuth2客户端的注册信息和提供商的具体配置。</li><li><strong>安全过滤器链配置</strong>：通过继承<code>WebSecurityConfigurerAdapter</code>类并覆盖<code>configure(HttpSecurity http)</code>方法，定义哪些路径需要认证，启用OAuth2登录支持。</li><li><strong>自定义OAuth2用户服务</strong>（可选）：根据需求自定义处理获取到的用户信息的逻辑。</li></ul></li></ol><h3 id="reference" tabindex="-1"><a class="header-anchor" href="#reference" aria-hidden="true">#</a> Reference</h3>',9),_={href:"https://docs.spring.io/spring-security/reference/servlet/architecture.html",target:"_blank",rel:"noopener noreferrer"},A=e("p",null,"AccountAuthenticationProvider",-1),S=e("p",null,[e("img",{src:d,alt:"AccountAuthenticationProvider"})],-1),m=e("p",null,"Authentication",-1),v=e("p",null,[e("img",{src:a,alt:"Authentication"})],-1),y=e("p",null,"UserDetails",-1),b=e("p",null,[e("img",{src:u,alt:"Authentication"})],-1),f=e("p",null,"CustomToken",-1),x=e("p",null,[e("img",{src:p,alt:"Authentication"})],-1);function C(P,T){const t=i("ExternalLinkIcon");return n(),l("div",null,[h,e("ul",null,[e("li",null,[e("a",_,[r("architecture"),c(t)])])]),A,S,m,v,y,b,f,x])}const D=o(g,[["render",C],["__file","/home/runner/work/vuepress_blog/vuepress_blog/docs/.vuepress/.temp/pages/java/springSecurity.html.vue"]]);export{D as default};
